// Top-customers report for the finance dashboard.
// orders: [{ id, customerId, status, amountCents, currency: 'USD' | 'EUR', createdAt: ISO-8601 string }]
const EUR_TO_USD = 1.08;

function byRank(a, b) {
  if (a.spendCents !== b.spendCents) return b.spendCents - a.spendCents;
  if (a.firstOrderAt !== b.firstOrderAt) return a.firstOrderAt < b.firstOrderAt ? -1 : 1;
  return a.customerId < b.customerId ? -1 : a.customerId > b.customerId ? 1 : 0;
}

function addOrder(group, order) {
  group.orderCount++;
  if (order.createdAt < group.firstOrderAt) group.firstOrderAt = order.createdAt;
  if (order.status === 'paid') {
    group.spendCents += order.currency === 'EUR' ? Math.round(order.amountCents * EUR_TO_USD) : order.amountCents;
  }
}

function newGroup(order) {
  return { customerId: order.customerId, spendCents: 0, orderCount: 0, firstOrderAt: order.createdAt };
}

function toReport(sortedGroups, limit) {
  return sortedGroups
    .filter((g) => g.spendCents > 0)
    .slice(0, limit)
    .map((g, i) => ({ rank: i + 1, ...g }));
}

// byRank is a strict total order (so one final sort gives the same result as
// re-sorting after every order) only when every group has a finite numeric
// spend and string firstOrderAt/customerId, with customerIds unique.
function hasWellFormedKeys(group) {
  return (
    typeof group.spendCents === 'number' && Number.isFinite(group.spendCents) &&
    typeof group.firstOrderAt === 'string' &&
    typeof group.customerId === 'string'
  );
}

// The original algorithm: re-sorts the leaderboard after every order, so the
// result for malformed data (where byRank is inconsistent) depends on that
// sequence. O(n * groups log groups); only used as a fallback for such data.
function summarizeIncremental(orders, limit) {
  const seen = new Set();
  const groups = [];
  for (const order of orders) {
    if (seen.has(order.id)) continue;
    seen.add(order.id);
    if (order.status === 'refunded') continue;

    let group = groups.find((g) => g.customerId === order.customerId);
    if (!group) {
      group = newGroup(order);
      groups.push(group);
    }
    addOrder(group, order);
    groups.sort(byRank);
  }
  return toReport(groups, limit);
}

function summarize(orders, limit = 10) {
  // Materialize one-shot iterables so the fallback can replay them.
  const list = Array.isArray(orders) ? orders : Array.from(orders);
  const seen = new Set();
  const groups = new Map();
  for (const order of list) {
    // Upstream retries can deliver the same order twice.
    if (seen.has(order.id)) continue;
    seen.add(order.id);
    if (order.status === 'refunded') continue;

    let group = groups.get(order.customerId);
    if (!group) {
      group = newGroup(order);
      groups.set(order.customerId, group);
    }
    addOrder(group, order);
  }

  const all = [...groups.values()];
  if (!all.every(hasWellFormedKeys)) return summarizeIncremental(list, limit);
  // Filtering first is safe: it doesn't depend on order, and the sort is total.
  return toReport(all.filter((g) => g.spendCents > 0).sort(byRank), limit);
}

